import struct, csv, sys

BOOL_TRUE=1; BOOL_FALSE=2; BYTE=3; I16=4; I32=5; I64=6; DOUBLE=7; BINARY=8; LIST=9; SET=10; MAP=11; STRUCT=12

def write_varint(buf, n):
    n &= 0xFFFFFFFFFFFFFFFF
    while True:
        b = n & 0x7f
        n >>= 7
        if n:
            buf.append(b | 0x80)
        else:
            buf.append(b)
            break

def zigzag(n):
    return (n << 1) if n >= 0 else ((-n) << 1) - 1

def write_struct(buf, fields):
    fields = sorted(fields, key=lambda f: f[0])
    prev = 0
    for fid, ttype, val in fields:
        delta = fid - prev
        if delta < 15:
            buf.append((delta << 4) | ttype)
        else:
            buf.append(0xf0 | ttype)
            write_varint(buf, delta - 15)
        val(buf)
        prev = fid
    buf.append(0)

def render_i32(x):
    def r(b): write_varint(b, zigzag(x))
    return r

def render_i64(x):
    def r(b): write_varint(b, zigzag(x))
    return r

def render_double(x):
    def r(b): b.extend(struct.pack('<d', x))
    return r

def render_binary(x):
    def r(b):
        write_varint(b, len(x))
        b.extend(x)
    return r

def render_bool(x):
    def r(b): b.append(BOOL_TRUE if x else BOOL_FALSE)
    return r

def render_raw(data):
    def r(b): b.extend(data)
    return r

def render_struct(fields):
    def r(b): write_struct(b, fields)
    return r

def render_list(etype, items, item_render):
    def r(b):
        n = len(items)
        if n < 15:
            b.append((n << 4) | etype)
        else:
            b.append(0xf0 | etype)
            write_varint(b, n)
        for it in items:
            item_render(it)(b)
    return r

def page_header(num_values, data_size):
    dph = [
        (1, I32, render_i32(num_values)),
        (2, I32, render_i32(0)),
        (3, I32, render_i32(3)),
        (4, I32, render_i32(3)),
    ]
    fields = [
        (1, I32, render_i32(0)),
        (2, I32, render_i32(data_size)),
        (3, I32, render_i32(data_size)),
        (5, STRUCT, render_struct(dph)),
    ]
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def stats_fields(min_b, max_b, null_count=0):
