        (1, BINARY, render_binary(max_b)),
        (2, BINARY, render_binary(min_b)),
        (3, I64, render_i64(null_count)),
        (5, BINARY, render_binary(max_b)),
        (6, BINARY, render_binary(min_b)),
    ]

def column_meta(col_type, path, num_values, uncompressed, compressed, data_page_offset, stats):
    fields = [
        (1, I32, render_i32(col_type)),
        (2, LIST, render_list(I32, [0, 3], render_i32)),
        (3, LIST, render_list(BINARY, [p.encode() for p in path], render_binary)),
        (4, I32, render_i32(0)),
        (5, I64, render_i64(num_values)),
        (6, I64, render_i64(uncompressed)),
        (7, I64, render_i64(compressed)),
        (9, I64, render_i64(data_page_offset)),
        (12, STRUCT, render_struct(stats)),
    ]
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def column_chunk(file_offset, meta_bytes):
    fields = [
        (1, I64, render_i64(file_offset)),
        (2, STRUCT, render_raw(meta_bytes)),
    ]
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def row_group(col_chunks, total_uncompressed, num_rows, total_compressed):
    fields = [
        (1, LIST, render_list(STRUCT, col_chunks, render_raw)),
        (2, I64, render_i64(total_uncompressed)),
        (3, I64, render_i64(num_rows)),
        (6, I64, render_i64(total_compressed)),
    ]
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def schema_element(name, type_code=None, num_children=None, converted_type=None, repetition=1):
    fields = []
    if type_code is not None:
        fields.append((1, I32, render_i32(type_code)))
    if num_children is not None:
        fields.append((5, I32, render_i32(num_children)))
    fields.append((3, I32, render_i32(repetition)))
    fields.append((4, BINARY, render_binary(name.encode())))
    if converted_type is not None:
        fields.append((6, I32, render_i32(converted_type)))
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def file_meta(row_group_bytes, schema_bytes, num_rows):
    fields = [
        (1, I32, render_i32(1)),
        (2, LIST, render_list(STRUCT, schema_bytes, render_raw)),
        (3, I64, render_i64(num_rows)),
        (4, LIST, render_list(STRUCT, row_group_bytes, render_raw)),
        (6, BINARY, render_binary(b"codebuddy-parquet-writer")),
    ]
    buf = bytearray()
    write_struct(buf, fields)
    return bytes(buf)

def is_int(s):
    try:
