    except: return False

def is_float(s):
    try:
        float(s); return True
    except: return False

def main():
    in_path = '/app/data.csv'
    out_path = '/app/data.parquet'
    with open(in_path, 'r', newline='') as f:
        reader = csv.reader(f)
        rows = [r for r in reader if r]
    header = rows[0]
    data_rows = rows[1:]
    ncols = len(header)
    nrows = len(data_rows)
    cols = []
    for j in range(ncols):
        vals = [r[j] for r in data_rows]
        if vals and all(is_int(v) for v in vals):
            ivals = [int(v) for v in vals]
            page = b''.join(struct.pack('<q', x) for x in ivals)
            mn = min(ivals).to_bytes(8, 'little', signed=True)
            mx = max(ivals).to_bytes(8, 'little', signed=True)
            col_type = 2
            converted = None
        elif vals and all(is_float(v) for v in vals):
            fvals = [float(v) for v in vals]
            page = b''.join(struct.pack('<d', x) for x in fvals)
            mn = struct.pack('<d', min(fvals))
            mx = struct.pack('<d', max(fvals))
            col_type = 5
            converted = None
        else:
            bvals = [v.encode('utf-8') for v in vals]
            page = b''.join(struct.pack('<i', len(b)) + b for b in bvals)
            mn = min(bvals)
            mx = max(bvals)
            col_type = 6
            converted = 1
        cols.append({'name': header[j], 'col_type': col_type, 'converted': converted, 'page': page, 'mn': mn, 'mx': mx})
    out = bytearray()
    out.extend(b'PAR1')
    pos = 4
    col_chunks = []
    total_uncompressed = 0
    total_compressed = 0
    for c in cols:
        ph = page_header(nrows, len(c['page']))
        data_page_offset = pos
        out.extend(ph)
        pos += len(ph)
        out.extend(c['page'])
        pos += len(c['page'])
        st = stats_fields(c['mn'], c['mx'])
        meta = column_meta(c['col_type'], [c['name']], nrows, len(ph) + len(c['page']), len(ph) + len(c['page']), data_page_offset, st)
        cc = column_chunk(pos, meta)
        col_chunks.append(cc)
        total_uncompressed += len(ph) + len(c['page'])
        total_compressed += len(ph) + len(c['page'])
    schema = [schema_element('schema', num_children=ncols)]
    for c in cols:
        schema.append(schema_element(c['name'], type_code=c['col_type'], converted_type=c['converted']))
    rg = row_group(col_chunks, total_uncompressed, nrows, total_compressed)
    fm = file_meta(rg, schema, nrows)
    out.extend(fm)
    out.extend(struct.pack('<I', len(fm)))
    out.extend(b'PAR1')
    with open(out_path, 'wb') as f:
        f.write(out)
    print('Wrote', out_path, 'size', len(out), 'rows', nrows, 'cols', ncols)

main()
