        if b == 0: return None
        delta = (b >> 4) & 0xf; t = b & 0xf
        if delta == 15: delta = self.varint()
        return (delta, t)
    def val(self, t):
        if t == 1: return True
        if t == 2: return False
        if t == 3: self.i += 1; return None
        if t == 4: return self.zz(self.varint())
        if t == 5: return self.zz(self.varint())
