    def r(b): write_varint(b, zigzag(x))
    return r

def render_i64(x):
    def r(b): write_varint(b, zigzag(x))
    return r

def render_double(x):
    def r(b): b.extend(struct.pack('<d', x))
    return r

def render_binary(x):
    def r(b):
